static int cmpInt(const void* x, const void* y) {
    int p = *(const int*) x, q = *(const int*) y;
    return (p > q) - (p < q);
}

int kthOfTwo(int* a, int aSize, int* b, int bSize, int k) {
    int* all = malloc((aSize + bSize) * sizeof(int) + 1);
    memcpy(all, a, aSize * sizeof(int));
    memcpy(all + aSize, b, bSize * sizeof(int));
    qsort(all, aSize + bSize, sizeof(int), cmpInt);
    int answer = all[k - 1];
    free(all);
    return answer;
}

