class Solution:
    def kthOfTwo(self, a: List[int], b: List[int], k: int) -> int:
        i = j = 0
        for _ in range(k):
            if j == len(b) or (i < len(a) and a[i] <= b[j]):
                value = a[i]
                i += 1
            else:
                value = b[j]
                j += 1
        return value

