class Solution:
    def kthOfTwo(self, a: List[int], b: List[int], k: int) -> int:
        if len(a) > len(b):
            a, b = b, a
        m, n = len(a), len(b)
        lo, hi = max(0, k - n), min(k, m)
        while lo < hi:
            i = (lo + hi) // 2
            if a[i] < b[k - i - 1]:
                lo = i + 1
            else:
                hi = i
        i, j = lo, k - lo
        left_a = a[i - 1] if i > 0 else float("-inf")
        left_b = b[j - 1] if j > 0 else float("-inf")
        return max(left_a, left_b)

