class Solution {
    public int kthOfTwo(int[] a, int[] b, int k) {
        if (a.length > b.length) { int[] t = a; a = b; b = t; }
        int m = a.length, n = b.length;
        int lo = Math.max(0, k - n), hi = Math.min(k, m);
        while (lo < hi) {
            int i = lo + (hi - lo) / 2;
            if (a[i] < b[k - i - 1]) lo = i + 1;
            else hi = i;
        }
        int i = lo, j = k - lo;
        if (i == 0) return b[j - 1];
        if (j == 0) return a[i - 1];
        return Math.max(a[i - 1], b[j - 1]);
    }
}

