int kthOfTwo(int* a, int aSize, int* b, int bSize, int k) {
    if (aSize > bSize) return kthOfTwo(b, bSize, a, aSize, k);
    int m = aSize, n = bSize;
    int lo = k - n > 0 ? k - n : 0, hi = k < m ? k : m;
    while (lo < hi) {
        int i = lo + (hi - lo) / 2;
        if (a[i] < b[k - i - 1]) lo = i + 1;
        else hi = i;
    }
    int i = lo, j = k - lo;
    if (i == 0) return b[j - 1];
    if (j == 0) return a[i - 1];
    return a[i - 1] > b[j - 1] ? a[i - 1] : b[j - 1];
}
